func (r *SymbolResolver) initPatterns() {
	// A股代码规范化
	r.patterns = append(r.patterns, &symbolPattern{
		regex:       regexp.MustCompile(`^6\d{5}$`),
		replacement: "${0}.SS", // 上海
	})
	r.patterns = append(r.patterns, &symbolPattern{
		regex:       regexp.MustCompile(`^[03]\d{5}$`),
		replacement: "${0}.SZ", // 深圳
	})

	// 港股代码规范化
	r.patterns = append(r.patterns, &symbolPattern{
		regex:       regexp.MustCompile(`^(\d{4,5})\.?HK$`),
		replacement: "${1}.HK",
	})
}

var (
	reExchCN6Digits = regexp.MustCompile(`^\d{6}$`)
	reExchHKDigits  = regexp.MustCompile(`^\d{1,5}$`)
)

// normalizeExchangePrefix 将 Futu/Longport 风格的交易所前缀符号
// (US.SPY / SH.600519 / SZ.000001 / HK.700) 转换为 Yahoo 风格
// (SPY / 600519.SS / 000001.SZ / 0700.HK)。前缀大小写不敏感；未命中时原样返回。
func normalizeExchangePrefix(symbol string) string {
	upper := strings.ToUpper(symbol)
	switch {
	case strings.HasPrefix(upper, "US."):
		return strings.ToUpper(symbol[len("US."):])
	case strings.HasPrefix(upper, "SH."):
		ticker := symbol[len("SH."):]
		if reExchCN6Digits.MatchString(ticker) {
			return ticker + ".SS"
		}
	case strings.HasPrefix(upper, "SZ."):
		ticker := symbol[len("SZ."):]
		if reExchCN6Digits.MatchString(ticker) {
			return ticker + ".SZ"
		}
	case strings.HasPrefix(upper, "HK."):
		ticker := symbol[len("HK."):]
		if reExchHKDigits.MatchString(ticker) {
			code := strings.TrimLeft(ticker, "0")
			for len(code) < 4 {
				code = "0" + code
			}
			return code + ".HK"
		}
	}
	return symbol
}

// Resolve 解析符号
func (r *SymbolResolver) Resolve(symbol string) string {
	symbol = strings.TrimSpace(symbol)
	symbol = normalizeExchangePrefix(symbol)
	upper := strings.ToUpper(symbol)

	// 检查别名
	if resolved, ok := r.aliases[symbol]; ok {
		return resolved
	}
	if resolved, ok := r.aliases[upper]; ok {
		return resolved
	}

	// 应用模式匹配
	for _, p := range r.patterns {
		if p.regex.MatchString(symbol) {
			return p.regex.ReplaceAllString(symbol, p.replacement)
		}
		if p.regex.MatchString(upper) {
			return p.regex.ReplaceAllString(upper, p.replacement)
		}
	}

	return symbol
}

// AddAlias 添加别名
func (r *SymbolResolver) AddAlias(alias, symbol string) {
	r.aliases[alias] = symbol
}

// HasAlias 检查是否有别名
func (r *SymbolResolver) HasAlias(alias string) bool {
	_, ok := r.aliases[alias]
	return ok
}

var (
	reCanonHK     = regexp.MustCompile(`^(\d{1,5})\.HK$`)
	reCanonCN     = regexp.MustCompile(`^(\d{6})\.(SS|SZ)$`)
	reCanonUS     = regexp.MustCompile(`^[A-Z]{1,6}(\.[A-Z])?$`)
	reCanonCrypto = regexp.MustCompile(`^([A-Z0-9]{2,10})(USDT|USDC|USD)$`)
)

// ToCanonical converts a resolver-format symbol (Yahoo/Binance style, e.g.
// "AAPL" / "600519.SS" / "0700.HK" / "BTCUSDT") into the canonical symbol
// contract (US:AAPL / CN:600519 / HK:00700 / CRYPTO:BTC-USD). This makes the
// resolver an adapter onto the canonical contract (docs/contracts/symbol.md)
// additively — the existing Resolve output format is unchanged. Returns "" if
// the input is not a recognized format.
func ToCanonical(resolved string) string {
	s := strings.TrimSpace(resolved)
	if s == "" {
		return ""
	}
	if m := reCanonCN.FindStringSubmatch(s); m != nil {
		return "CN:" + m[1]
	}
	if m := reCanonHK.FindStringSubmatch(s); m != nil {
		code := m[1]
		for len(code) < 5 {
			code = "0" + code
		}
		return "HK:" + code
	}
	if m := reCanonCrypto.FindStringSubmatch(s); m != nil {
		return "CRYPTO:" + m[1] + "-USD"
	}
	if reCanonUS.MatchString(s) {
		return "US:" + s
	}
	return ""
}

// ResolveCanonical resolves an alias/name to a symbol, then maps it to the
// canonical contract. Returns "" if the resolved symbol has no canonical form.
func (r *SymbolResolver) ResolveCanonical(symbol string) string {
	return ToCanonical(r.Resolve(symbol))
}
